"""Original-source-gated Native setup for the C412262 narrow-highway parking plan."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from highway_observations import point


ASSIGNMENT = "testing__C412262__NRS-484B-490__motor_vehicle_driver"
SOURCE_FIELDS = ("map_sha256", "dedication_sha256", "boundary_sha256", "public_access_sha256",
                 "width_survey_sha256", "device_erection_sha256", "device_authority_sha256",
                 "device_content_sha256", "device_conformity_sha256", "device_extent_sha256",
                 "activity_source_sha256")


def load_case(case_id: str) -> dict:
    plan = json.loads((Path(__file__).resolve().parent / "case-plan.json").read_text())
    case = next((item for item in plan["cases"] if item["case_id"] == case_id), None)
    if case is None or not case_id.startswith(ASSIGNMENT + "__"):
        raise ValueError("unknown exact narrow-highway parking case")
    return case


def validate_site(path: str | Path, case_id: str) -> dict:
    case = load_case(case_id)
    source_path = Path(path).resolve()
    raw = source_path.read_bytes()
    site = json.loads(raw)
    if (site.get("assignment_id") != ASSIGNMENT or site.get("cell_id") != "C412262" or
            site.get("source_kind") != "original_reviewed_highway_site" or
            site.get("review_status") != "reviewed"):
        raise ValueError("reviewed original highway site identity required")
    for field in SOURCE_FIELDS:
        value = site.get(field)
        if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
            raise ValueError("reviewed original source hash required: " + field)
        record = site.get("source_records", {}).get(field)
        if not isinstance(record, dict) or not isinstance(record.get("path"), str):
            raise ValueError("reviewed original source record required: " + field)
        relative = Path(record["path"])
        if relative.is_absolute() or ".." in relative.parts or not relative.parts:
            raise ValueError("reviewed original source path escapes site: " + field)
        unresolved = source_path.parent / relative
        target = unresolved.resolve()
        if (source_path.parent not in target.parents or unresolved.is_symlink() or
                not target.is_file() or record.get("sha256") != value or
                hashlib.sha256(target.read_bytes()).hexdigest() != value):
            raise ValueError("reviewed original source bytes changed: " + field)
    for key, expected in (("highway_width_variant", case["highway_width_request"]),
                          ("device_variant", case["device_request"]),
                          ("parking_location_variant", case["parking_location_request"])):
        if site.get(key) != expected:
            raise ValueError("reviewed site differs from exact case: " + key)
    for key in ("highway_boundary_xy_m", "device_extent_xy_m"):
        vertices = site.get(key)
        if not isinstance(vertices, list) or len(vertices) < 3:
            raise ValueError("reviewed full polygon required: " + key)
        for vertex in vertices:
            point(vertex)
    profile = site.get("full_highway_width_profile_m")
    if not isinstance(profile, list) or len(profile) < 2 or any(not isinstance(x, (int, float)) or x <= 0 for x in profile):
        raise ValueError("reviewed full highway width profile required")
    route = site.get("lane_route_xy_m")
    if not isinstance(route, list) or len(route) < 2:
        raise ValueError("reviewed lane route required")
    for vertex in route:
        point(vertex)
    device = site.get("device")
    if not isinstance(device, dict):
        raise ValueError("reviewed traffic-control device survey required")
    if case["device_request"] != "absent":
        for key in ("blueprint_id", "exact_instruction_text", "erecting_authority_id",
                    "conformity_source_id", "governing_extent_id"):
            if not isinstance(device.get(key), str) or not device[key]:
                raise ValueError("reviewed device field required: " + key)
    site["_source_sha256"] = hashlib.sha256(raw).hexdigest()
    return site


def construct(adapter, site_path: str | Path, case_id: str) -> dict:
    case = load_case(case_id)
    site = validate_site(site_path, case_id)
    owned = []
    try:
        adapter.configure_highway(site["lane_route_xy_m"], site["highway_boundary_xy_m"],
                                  site["full_highway_width_profile_m"])
        highway = adapter.read_highway()
        if not isinstance(highway, dict) or highway.get("boundary_xy_m") != site["highway_boundary_xy_m"]:
            raise ValueError("Native highway boundary readback differs")
        if highway.get("width_profile_m") != site["full_highway_width_profile_m"]:
            raise ValueError("Native full highway width readback differs")
        if case["device_request"] != "absent":
            device = adapter.spawn_device(site["device"])
            if not device:
                raise ValueError("prohibitory traffic-control device spawn failed")
            owned.append(device)
        observed_device = adapter.read_device()
        if not isinstance(observed_device, dict) or observed_device.get("state") != site["device_variant"]:
            raise ValueError("Native device erection and extent readback differs")
        if case["device_request"] != "absent":
            for key in ("exact_instruction_text", "erecting_authority_id", "conformity_source_id",
                        "governing_extent_id"):
                if observed_device.get(key) != site["device"][key]:
                    raise ValueError("Native device authority or content readback differs: " + key)
        vehicle = adapter.spawn_vehicle(site["lane_route_xy_m"][0])
        if not vehicle:
            raise ValueError("subject vehicle spawn failed")
        owned.append(vehicle)
        adapter.drive_to_parking_location(vehicle, case["parking_location_request"], site["lane_route_xy_m"])
        adapter.hold_for_activity(vehicle, case["activity_request"])
        observed_vehicle = adapter.read_vehicle_state(vehicle)
        if not isinstance(observed_vehicle, dict) or observed_vehicle.get("activity_request") != case["activity_request"]:
            raise ValueError("Native vehicle activity readback differs")
        return {"case_id": case_id, "site_source_sha256": site["_source_sha256"],
                "owned": tuple(owned), "physical_limit": "Original highway geometry, device pixels and actual parking activity require post-capture review."}
    except Exception:
        for actor in reversed(owned):
            adapter.destroy(actor)
        raise

"""Source-bound geometry checks for NRS 484B.490; no legal width cutoff."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def point(value):
    if not isinstance(value, list) or len(value) != 2 or any(not isinstance(v, (int, float)) for v in value):
        raise ValueError("finite planar point required")
    return tuple(float(v) for v in value)


def cross(a, b, p):
    return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])


def inside(p, polygon):
    vertices = [point(v) for v in polygon]
    if len(vertices) < 3:
        raise ValueError("full highway boundary polygon required")
    contained = False
    for index, a in enumerate(vertices):
        b = vertices[(index + 1) % len(vertices)]
        area = cross(a, b, p)
        if abs(area) <= 1e-8 and min(a[0], b[0]) - 1e-8 <= p[0] <= max(a[0], b[0]) + 1e-8 and min(a[1], b[1]) - 1e-8 <= p[1] <= max(a[1], b[1]) + 1e-8:
            return True
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
                contained = not contained
    return contained


def observe(case_id: str, context_path: Path, trace_path: Path, receipt_path: Path) -> dict:
    from highway_scene_construction import load_case

    case = load_case(case_id)
    context = json.loads(context_path.read_text())
    receipt = json.loads(receipt_path.read_text())
    if context.get("assignment_id") != case_id.rsplit("__", 1)[0] or context.get("case_id") != case_id:
        raise ValueError("original highway context identity mismatch")
    for key in ("highway_width_request", "device_request", "activity_request", "parking_location_request"):
        if context.get(key) != case[key]:
            raise ValueError("original highway context differs from exact case: " + key)
    if receipt.get("context_sha256") != sha(context_path) or receipt.get("trace_sha256") != sha(trace_path):
        raise ValueError("original highway context or trace seal mismatch")
    if context.get("source_kind") != "original_reviewed_highway_site":
        raise ValueError("original reviewed highway source required")
    for key in ("map_sha256", "dedication_sha256", "boundary_sha256", "public_access_sha256",
                "width_survey_sha256", "device_erection_sha256", "device_authority_sha256",
                "device_content_sha256", "device_conformity_sha256", "device_extent_sha256",
                "activity_source_sha256"):
        value = context.get(key)
        if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
            raise ValueError("reviewed source hash required: " + key)
    highway = context.get("highway_boundary_xy_m")
    extent = context.get("device_extent_xy_m")
    rows = [json.loads(line) for line in trace_path.read_text().splitlines()]
    if len(rows) != receipt.get("frame_count") or not rows:
        raise ValueError("original highway frame count mismatch")
    samples = []
    for index, row in enumerate(rows):
        if row.get("frame") != index or abs(row.get("time_s", -1) - index / 20) > 0.002:
            raise ValueError("original highway 20 Hz cadence mismatch")
        body = [point(v) for v in row.get("vehicle_body_polygon_xy_m", [])]
        if len(body) < 4:
            raise ValueError("full subject body footprint required")
        if not isinstance(row.get("speed_mps"), (int, float)):
            raise ValueError("actual subject speed missing")
        samples.append({"frame": index, "time_s": row["time_s"], "speed_mps": row["speed_mps"],
                        "body_on_highway": all(inside(p, highway) for p in body),
                        "body_in_device_extent": all(inside(p, extent) for p in body)})
    return {"case_id": case_id, "samples": samples,
            "full_highway_width_profile_m": context.get("full_highway_width_profile_m"),
            "highway_status_source_label": context.get("highway_status"),
            "device_source_label": context.get("device_status"),
            "activity_source_label": context.get("activity_status"),
            "narrow_highway_judgment": "unresolved",
            "official_device_judgment": "unresolved",
            "parking_judgment": "unresolved",
            "statutory_disposition": "unresolved_pending_original_review",
            "physical_acceptance": "unverified"}

"""Independent original-source audit for all narrow-highway parking cases."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from comparison_audit import audit as compare
from saved_finalizer import finalize
from highway_scene_construction import ASSIGNMENT


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def audit(index_path: Path) -> dict:
    index_path = Path(index_path)
    index = json.loads(index_path.read_text())
    plan = json.loads((Path(__file__).resolve().parent / "case-plan.json").read_text())
    if index.get("assignment_id") != ASSIGNMENT or index.get("source_kind") != "original_native_delivery":
        raise ValueError("original delivery index identity/source mismatch")
    cases = index.get("cases")
    expected = {case["case_id"] for case in plan["cases"]}
    if not isinstance(cases, dict) or set(cases) != expected:
        raise ValueError("every exact original delivery case required")
    packets = {}
    for case_id, names in cases.items():
        if not isinstance(names, dict) or set(names) != {"context", "trace", "receipt", "camera_manifest", "measurement"}:
            raise ValueError("original delivery source inventory incomplete: " + case_id)
        paths = {}
        for key, item in names.items():
            if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
                raise ValueError("original delivery source binding missing: " + case_id)
            relative = Path(item["path"])
            if relative.is_absolute() or ".." in relative.parts:
                raise ValueError("original delivery source path escapes index")
            origin = index_path.parent.resolve()
            unresolved = origin / relative
            path = unresolved.resolve()
            if (origin not in path.parents or unresolved.is_symlink() or
                    not path.is_file() or sha(path) != item["sha256"]):
                raise ValueError("original delivery source changed: " + case_id + ": " + key)
            paths[key] = path
        measured = finalize(case_id, paths["context"], paths["trace"], paths["receipt"],
                            paths["camera_manifest"])
        saved = json.loads(paths["measurement"].read_text())
        if saved != measured or saved.get("physical_acceptance") != "unverified":
            raise ValueError("saved original measurement differs or overclaims: " + case_id)
        packets[case_id] = paths
    comparisons = {}
    for row in plan["comparisons"]:
        left, right = row["case_ids"]
        packet = lambda key: {"case_id": key, "context": str(packets[key]["context"]),
                              "trace": str(packets[key]["trace"]),
                              "receipt": str(packets[key]["receipt"])}
        comparisons[row["comparison_id"]] = compare(row["comparison_id"], packet(left), packet(right))
    return {"assignment_id": ASSIGNMENT, "source_kind": "original_native_delivery",
            "case_count": len(packets), "comparison_count": len(comparisons),
            "index_sha256": sha(index_path), "legal_judgment": "unresolved",
            "physical_acceptance": "unverified",
            "comparisons": comparisons}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--index", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    args.output.write_text(json.dumps(audit(args.index), sort_keys=True, indent=2) + "\n")


if __name__ == "__main__":
    main()
